r#"//// The package `{name}`. It imports the standard service `Io` from `i/io`
//// (§9.7), and `i run` gives it, so the program can print.

((Io) = i/io)

(greeting)

/// The greeting for `who`.
greeting = (who : String) -> String {{ "Hello, " <> who <> "!" }}

main = () <- (io : Io) {{
  io.print(greeting("{name}"))
}}
"#

r#"(
	i/fail
)

(
	divide
	check
	positive
	bits
)

// The errors are `String | Int`, given to the host in the canonical
// order: `Int` is member 1 and `String` member 2 (B.2).
divide = (a : Int, b : Int) {
	b |>
		(0) { fail.raise("division by zero") }
		| (1) { fail.raise(a) }
		| (_) { a / b }
}

// `Nil` and `Bool` errors have their own tags.
check = (n : Int) -> Float {
	n |> (0) { fail.raise(Nil) } | (1) { fail.raise(True) } | (_) { 1.5 }
}

// The `Assert` of a host export stops the program (§9.6).
positive = (n : Int) {
	assert(n > 0)
	n
}

// A `BitArray` error.
bits = (b : Bool) -> Nil {
	b |> (True) { fail.raise(<<1, 2>>) } | (False) { Nil }
}
"#
